fun formatFileSize(bytes: Long): String {
    if (bytes < 1024) return "$bytes B"
    val units = arrayOf("KB", "MB", "GB", "TB")
    var size = bytes.toDouble()
    for (unit in units) {
        if (size < 1024) return "%.1f $unit".format(size, unit).replace(".0 ", "")
        size /= 1024
    }
    return "%.1f PB".format(size)
}
```
This function divides the byte count by 1024 iteratively, selecting the appropriate unit (B, KB, MB, etc.). It formats the result to one decimal place, removing trailing ".0" for cleaner output like "832 KB" or "1.5 MB".
